1	import { useEffect, useState } from "react";
2	import { api, getAccessCode, setAccessCode, useAction, usePoll } from "./api.js";
3	import { titleCase } from "./format.js";
4	import Audit from "./components/Audit.jsx";
5	import { Badge, Button, ErrorNote } from "./components/common.jsx";
6	import Incidents from "./components/Incident.jsx";
7	import Overview from "./components/Overview.jsx";
8	import ScenarioLab from "./components/ScenarioLab.jsx";
9	
10	const TABS = [
11	  ["overview", "Overview"],
12	  ["lab", "Scenario lab"],
13	  ["incidents", "Incidents"],
14	  ["audit", "Audit log"],
15	];
16	const TRUST_TEXT = {
17	  trustworthy: "Data is trustworthy",
18	  under_investigation: "Under investigation",
19	  stale: "Data is stale",
20	  untrusted: "Data does not reconcile",
21	};
22	
23	// The view lives in the URL hash (#/incidents/INC-0001) so a reload or a
24	// shared link lands on the same page.
25	function readRoute() {
26	  const [tab, id] = window.location.hash.replace(/^#\/?/, "").split("/");
27	  return { tab: TABS.some(([key]) => key === tab) ? tab : "overview", id: id || null };
28	}
29	
30	export default function App() {
31	  const [route, setRoute] = useState(readRoute);
32	  const [code, setCode] = useState(getAccessCode);
33	  const [confirmingReset, setConfirmingReset] = useState(false);
34	  const metrics = usePoll("/metrics/summary", 2500);
35	  const agent = usePoll("/agent/status", 5000);
36	  const health = usePoll("/health", 4000);
37	  const action = useAction();
38	
39	  useEffect(() => {
40	    const onHash = () => setRoute(readRoute());
41	    window.addEventListener("hashchange", onHash);
42	    return () => window.removeEventListener("hashchange", onHash);
43	  }, []);
44	
45	  const go = (tab, id) => {
46	    window.location.hash = id ? `/${tab}/${id}` : `/${tab}`;
47	  };
48	  const refreshAll = () => {
49	    metrics.refresh();
50	    agent.refresh();
51	    health.refresh();
52	  };
53	  const post = (path) =>
54	    action.run(async () => {
55	      await api(path, { method: "POST" });
56	      refreshAll();
57	    });
58	  // Reset wipes every incident, so it takes two clicks; the second must come
59	  // within a few seconds or the button returns to its first state.
60	  const reset = async () => {
61	    if (!confirmingReset) {
62	      setConfirmingReset(true);
63	      window.setTimeout(() => setConfirmingReset(false), 4000);
64	      return;
65	    }
66	    setConfirmingReset(false);
67	    await post("/demo/reset");
68	    go("overview");
69	  };
70	
71	  const trafficRunning = health.data?.traffic_running;
72	  const activeIncident = metrics.data?.active_incident;
73	  const trust = metrics.data?.trust;
74	
75	  return (
76	    <div className="app">
77	      <header className="topbar">
78	        <div className="brand">
79	          <span className="brand-mark" aria-hidden="true" />
80	          <div>
81	            <div className="brand-name">DataTraceMind</div>
82	            <div className="brand-tag">Agentic data reliability engineer</div>
83	          </div>
84	        </div>
85	        <div className="topbar-status">
86	          {trust && <Badge value={trust}>{TRUST_TEXT[trust]}</Badge>}
87	          {agent.data && (
88	            <Badge tone={agent.data.available ? (agent.data.investigation_running ? "active" : "good") : "warning"} title={agent.data.detail}>
89	              {agent.data.available
90	                ? agent.data.investigation_running
91	                  ? "Agent investigating"
92	                  : `Agent available · ${agent.data.model}`
93	                : "Agent unavailable"}
94	            </Badge>
95	          )}
96	        </div>
97	        <div className="topbar-actions">
98	          {agent.data?.access_code_required && (
99	            <input
100	              className="access-code"
101	              type="password"
102	              placeholder="Demo access code"
103	              aria-label="Demo access code"
104	              value={code}
105	              onChange={(event) => {
106	                setCode(event.target.value);
107	                setAccessCode(event.target.value);
108	              }}
109	            />
110	          )}
111	          <Button onClick={() => post(trafficRunning ? "/demo/traffic/stop" : "/demo/traffic/start")} busy={action.busy}>
112	            {trafficRunning ? "Stop traffic" : "Start traffic"}
113	          </Button>
114	          <Button
115	            onClick={reset}
116	            busy={action.busy}
117	            kind="danger"
118	            title="Restores the clean baseline and clears all incidents"
119	          >
120	            {confirmingReset ? "Click again to reset" : "Reset demo"}
121	          </Button>
122	        </div>
123	      </header>
124	
125	      <nav className="tabs" aria-label="Sections">
126	        {TABS.map(([key, label]) => (
127	          <button key={key} type="button" className={route.tab === key ? "active" : ""} onClick={() => go(key)}>
128	            {label}
129	            {key === "incidents" && activeIncident && <span className="tab-count">{titleCase(activeIncident.status)}</span>}
130	          </button>
131	        ))}
132	      </nav>
133	
134	      <main>
135	        <ErrorNote message={action.error} onDismiss={action.clearError} />
136	        {metrics.error && !metrics.data && <ErrorNote message={`Cannot reach the DataTraceMind API: ${metrics.error.message}`} />}
137	        {route.tab === "overview" && <Overview metrics={metrics.data} onOpenIncident={(id) => go("incidents", id)} />}
138	        {route.tab === "lab" && (
139	          <ScenarioLab onChanged={refreshAll} onOpenIncident={(id) => go("incidents", id)} activeIncident={activeIncident} />
140	        )}
141	        {route.tab === "incidents" && (
142	          <Incidents selectedId={route.id} onSelect={(id) => go("incidents", id)} agent={agent.data} onChanged={refreshAll} />
143	        )}
144	        {route.tab === "audit" && <Audit />}
145	      </main>
146	    </div>
147	  );
148	}
