1	// Scenario Lab: inject one known fault, or reset to the clean baseline.
2	import { api, useAction, usePoll } from "../api.js";
3	import { dateTime, money, signedMoney } from "../format.js";
4	import { Badge, Button, Card, Empty, ErrorNote } from "./common.jsx";
5	
6	function MetricsTable({ baseline, after }) {
7	  const currencies = Object.keys(baseline.by_currency);
8	  return (
9	    <table className="table numeric">
10	      <thead>
11	        <tr>
12	          <th>Currency</th>
13	          <th>Source-derived net</th>
14	          <th>Analytics net before</th>
15	          <th>Analytics net after</th>
16	          <th>Analytics vs source</th>
17	        </tr>
18	      </thead>
19	      <tbody>
20	        {currencies.map((currency) => {
21	          const before = baseline.by_currency[currency];
22	          const now = after?.by_currency[currency];
23	          return (
24	            <tr key={currency}>
25	              <td>{currency}</td>
26	              <td>{money((now || before).source.net, currency)}</td>
27	              <td>{money(before.analytics.net, currency)}</td>
28	              <td>{now ? money(now.analytics.net, currency) : "–"}</td>
29	              <td>
30	                {!now ? "–" : now.within_tolerance ? "matches" : signedMoney(now.net_difference, currency)}
31	              </td>
32	            </tr>
33	          );
34	        })}
35	      </tbody>
36	    </table>
37	  );
38	}
39	
40	export default function ScenarioLab({ onChanged, onOpenIncident, activeIncident }) {
41	  const { data, refresh } = usePoll("/scenarios", 4000);
42	  const action = useAction();
43	  if (!data) return <Empty>Loading scenarios…</Empty>;
44	  const active = data.active?.scenario_id;
45	
46	  async function inject(scenarioId) {
47	    const report = await action.run(() => api(`/scenarios/${scenarioId}/inject`, { method: "POST" }));
48	    await refresh();
49	    onChanged();
50	    if (report?.incident_id) onOpenIncident(report.incident_id);
51	  }
52	
53	  return (
54	    <div className="stack">
55	      <Card
56	        title="Scenario lab"
57	        subtitle="Each scenario introduces one deterministic fault into the demo environment. DataTraceMind is not told which one: it has to find the cause from the same evidence an engineer would have."
58	      >
59	        <ErrorNote message={action.error} onDismiss={action.clearError} />
60	        <div className="scenarios">
61	          {data.scenarios.map((scenario) => (
62	            <article key={scenario.scenario_id} className={`scenario ${active === scenario.scenario_id ? "scenario-active" : ""}`}>
63	              <header>
64	                <span className="scenario-id">{scenario.scenario_id}</span>
65	                <span className="muted">{scenario.failure_type}</span>
66	              </header>
67	              <h3>{scenario.name}</h3>
68	              <p>{scenario.description}</p>
69	              {active === scenario.scenario_id ? (
70	                <Badge tone="serious">Injected {dateTime(data.active.injected_at)}</Badge>
71	              ) : (
72	                <Button
73	                  onClick={() => inject(scenario.scenario_id)}
74	                  busy={action.busy}
75	                  disabled={Boolean(active)}
76	                  title={active ? "Reset the demo before injecting another scenario" : undefined}
77	                >
78	                  Inject fault
79	                </Button>
80	              )}
81	            </article>
82	          ))}
83	        </div>
84	        {active && (
85	          <p className="muted">
86	            {active} is injected. Reset the demo (top right) to return to the clean baseline before injecting another scenario.
87	            {activeIncident && (
88	              <>
89	                {" "}
90	                <button type="button" className="link" onClick={() => onOpenIncident(activeIncident.incident_id)}>
91	                  Open {activeIncident.incident_id}
92	                </button>
93	              </>
94	            )}
95	          </p>
96	        )}
97	      </Card>
98	
99	      {data.active?.baseline_metrics && (
100	        <Card title="Baseline versus post-injection" subtitle="Net revenue per currency, before the fault and after the first pipeline run with it.">
101	          <MetricsTable baseline={data.active.baseline_metrics} after={data.active.post_injection_metrics} />
102	        </Card>
103	      )}
104	    </div>
105	  );
106	}
