1	// Thin client for the DataTraceMind API, plus the polling hook the pages use.
2	import { useCallback, useEffect, useRef, useState } from "react";
3	
4	const ACCESS_CODE_KEY = "dtm-access-code";
5	
6	export function getAccessCode() {
7	  try {
8	    return window.localStorage.getItem(ACCESS_CODE_KEY) || "";
9	  } catch {
10	    return "";
11	  }
12	}
13	
14	export function setAccessCode(code) {
15	  try {
16	    if (code) window.localStorage.setItem(ACCESS_CODE_KEY, code);
17	    else window.localStorage.removeItem(ACCESS_CODE_KEY);
18	  } catch {
19	    // Storage can be unavailable (private window); the code then lasts for this page only.
20	  }
21	}
22	
23	export async function api(path, { method = "GET", body } = {}) {
24	  const headers = {};
25	  if (body !== undefined) headers["Content-Type"] = "application/json";
26	  const code = getAccessCode();
27	  if (code) headers["X-Demo-Access-Code"] = code;
28	  const response = await fetch(`/api${path}`, {
29	    method,
30	    headers,
31	    body: body === undefined ? undefined : JSON.stringify(body),
32	  });
33	  let payload = null;
34	  try {
35	    payload = await response.json();
36	  } catch {
37	    // A response without a JSON body; the status code carries the outcome.
38	  }
39	  if (!response.ok) {
40	    const detail = payload?.detail;
41	    const message = Array.isArray(detail)
42	      ? detail.map((d) => `${d.loc?.slice(1).join(".")}: ${d.msg}`).join("; ")
43	      : detail || `${response.status} ${response.statusText}`;
44	    const error = new Error(message);
45	    error.status = response.status;
46	    throw error;
47	  }
48	  return payload;
49	}
50	
51	// Poll `path` every `intervalMs`. Keeps the last good data while a refresh is
52	// in flight or failing, so the page never flashes empty.
53	export function usePoll(path, intervalMs = 2500) {
54	  const [data, setData] = useState(null);
55	  const [error, setError] = useState(null);
56	  const latest = useRef(path);
57	  latest.current = path;
58	
59	  const refresh = useCallback(async () => {
60	    if (!path) return;
61	    try {
62	      const next = await api(path);
63	      if (latest.current === path) {
64	        setData(next);
65	        setError(null);
66	      }
67	    } catch (err) {
68	      if (latest.current === path) setError(err);
69	    }
70	  }, [path]);
71	
72	  useEffect(() => {
73	    setData(null);
74	    setError(null);
75	    if (!path) return undefined;
76	    refresh();
77	    const timer = window.setInterval(refresh, intervalMs);
78	    return () => window.clearInterval(timer);
79	  }, [path, intervalMs, refresh]);
80	
81	  return { data, error, refresh };
82	}
83	
84	// Run a mutating call and expose its busy and error state to a button.
85	export function useAction() {
86	  const [busy, setBusy] = useState(false);
87	  const [error, setError] = useState(null);
88	  const run = useCallback(async (fn) => {
89	    setBusy(true);
90	    setError(null);
91	    try {
92	      return await fn();
93	    } catch (err) {
94	      setError(err.message);
95	      return undefined;
96	    } finally {
97	      setBusy(false);
98	    }
99	  }, []);
100	  return { busy, error, run, clearError: () => setError(null) };
101	}
