1	// Daily net revenue: what the source implies versus what analytics reports.
2	//
3	// Two series on one axis. Where the pipeline is correct the lines coincide, so
4	// days on which they differ get a marker: the gap is the story, and it must be
5	// findable without comparing two overlapping strokes.
6	import { useMemo, useRef, useState } from "react";
7	import { compactMoney, money, shortDate, signedMoney } from "../format.js";
8	
9	const WIDTH = 760;
10	const HEIGHT = 250;
11	const MARGIN = { top: 16, right: 20, bottom: 30, left: 62 };
12	const SERIES = [
13	  { key: "source_net", label: "Source-derived (contract)", className: "series-1" },
14	  { key: "analytics_net", label: "Analytics daily_revenue", className: "series-2" },
15	];
16	
17	function niceCeiling(value) {
18	  if (value <= 0) return 1;
19	  const magnitude = 10 ** Math.floor(Math.log10(value));
20	  const step = [1, 2, 2.5, 5, 10].find((m) => m * magnitude >= value);
21	  return step * magnitude;
22	}
23	
24	export default function RevenueChart({ daily, currency, tolerance = 0.01 }) {
25	  const rows = useMemo(() => daily.filter((d) => d.currency === currency), [daily, currency]);
26	  const [hover, setHover] = useState(null);
27	  const [showTable, setShowTable] = useState(false);
28	  const frame = useRef(null);
29	
30	  if (rows.length < 2) return <p className="empty">Not enough days of data to chart yet.</p>;
31	
32	  const innerWidth = WIDTH - MARGIN.left - MARGIN.right;
33	  const innerHeight = HEIGHT - MARGIN.top - MARGIN.bottom;
34	  const top = niceCeiling(Math.max(...rows.flatMap((r) => [r.source_net, r.analytics_net])));
35	  const x = (index) => MARGIN.left + (index / (rows.length - 1)) * innerWidth;
36	  const y = (value) => MARGIN.top + innerHeight - (Math.max(value, 0) / top) * innerHeight;
37	  const path = (key) => rows.map((r, i) => `${i === 0 ? "M" : "L"}${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).join(" ");
38	  const ticks = [0, 0.25, 0.5, 0.75, 1].map((share) => share * top);
39	  const labelEvery = Math.ceil(rows.length / 7);
40	  const differs = (row) => Math.abs(row.analytics_net - row.source_net) > tolerance;
41	  const mismatched = rows.filter(differs).length;
42	
43	  function onMove(event) {
44	    const box = frame.current.getBoundingClientRect();
45	    const position = ((event.clientX - box.left) / box.width) * WIDTH;
46	    const index = Math.round(((position - MARGIN.left) / innerWidth) * (rows.length - 1));
47	    setHover(Math.min(rows.length - 1, Math.max(0, index)));
48	  }
49	
50	  const active = hover === null ? null : rows[hover];
51	  const tooltipLeft = hover === null ? 0 : (x(hover) / WIDTH) * 100;
52	
53	  return (
54	    <div className="chart">
55	      <div className="chart-legend">
56	        {SERIES.map((series) => (
57	          <span key={series.key} className="legend-item">
58	            <span className={`legend-line ${series.className}`} aria-hidden="true" />
59	            {series.label}
60	          </span>
61	        ))}
62	        <span className="legend-item">
63	          <span className="legend-dot series-2" aria-hidden="true" />
64	          Day where they differ
65	        </span>
66	        <button type="button" className="link chart-toggle" onClick={() => setShowTable((v) => !v)}>
67	          {showTable ? "Show chart" : "Show as table"}
68	        </button>
69	      </div>
70	
71	      {showTable ? (
72	        <div className="table-scroll">
73	          <table className="table numeric">
74	            <thead>
75	              <tr>
76	                <th>Day</th>
77	                <th>Source-derived</th>
78	                <th>Analytics</th>
79	                <th>Difference</th>
80	              </tr>
81	            </thead>
82	            <tbody>
83	              {[...rows].reverse().map((row) => (
84	                <tr key={row.date}>
85	                  <td>{shortDate(row.date)}</td>
86	                  <td>{money(row.source_net, currency)}</td>
87	                  <td>{money(row.analytics_net, currency)}</td>
88	                  <td>{differs(row) ? signedMoney(row.analytics_net - row.source_net, currency) : "matches"}</td>
89	                </tr>
90	              ))}
91	            </tbody>
92	          </table>
93	        </div>
94	      ) : (
95	        <div className="chart-frame" ref={frame}>
96	          <svg
97	            viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
98	            role="img"
99	            aria-label={`Daily net revenue in ${currency}, source-derived versus analytics. ${mismatched} of ${rows.length} days differ.`}
100	            onPointerMove={onMove}
101	            onPointerLeave={() => setHover(null)}
102	          >
103	            {ticks.map((tick) => (
104	              <g key={tick}>
105	                <line className="grid" x1={MARGIN.left} x2={WIDTH - MARGIN.right} y1={y(tick)} y2={y(tick)} />
106	                <text className="axis" x={MARGIN.left - 8} y={y(tick)} textAnchor="end" dominantBaseline="middle">
107	                  {compactMoney(tick, currency)}
108	                </text>
109	              </g>
110	            ))}
111	            {rows.map(
112	              (row, index) =>
113	                (index % labelEvery === 0 || index === rows.length - 1) && (
114	                  <text key={row.date} className="axis" x={x(index)} y={HEIGHT - 8} textAnchor="middle">
115	                    {shortDate(row.date)}
116	                  </text>
117	                ),
118	            )}
119	            {active && <line className="crosshair" x1={x(hover)} x2={x(hover)} y1={MARGIN.top} y2={MARGIN.top + innerHeight} />}
120	            {SERIES.map((series) => (
121	              <path key={series.key} className={`line ${series.className}`} d={path(series.key)} />
122	            ))}
123	            {rows.map(
124	              (row, index) =>
125	                differs(row) && (
126	                  <circle key={row.date} className="marker series-2" cx={x(index)} cy={y(row.analytics_net)} r="4.5" />
127	                ),
128	            )}
129	            {active &&
130	              SERIES.map((series) => (
131	                <circle key={series.key} className={`marker ${series.className}`} cx={x(hover)} cy={y(active[series.key])} r="4.5" />
132	              ))}
133	          </svg>
134	          {active && (
135	            <div className={`tooltip ${tooltipLeft > 60 ? "tooltip-left" : ""}`} style={{ left: `${tooltipLeft}%` }}>
136	              <div className="tooltip-title">{shortDate(active.date)}</div>
137	              {SERIES.map((series) => (
138	                <div key={series.key} className="tooltip-row">
139	                  <span className={`legend-line ${series.className}`} aria-hidden="true" />
140	                  <strong>{money(active[series.key], currency)}</strong>
141	                  <span className="muted">{series.label}</span>
142	                </div>
143	              ))}
144	              <div className="tooltip-row tooltip-delta">
145	                {differs(active)
146	                  ? `Analytics is ${signedMoney(active.analytics_net - active.source_net, currency)} against the source`
147	                  : "Analytics matches the source"}
148	              </div>
149	            </div>
150	          )}
151	        </div>
152	      )}
153	      <p className="muted chart-note">
154	        {mismatched === 0
155	          ? "The two lines coincide on every day shown: analytics matches the source."
156	          : `${mismatched} of ${rows.length} days differ. The lines coincide wherever analytics matches the source.`}
157	      </p>
158	    </div>
159	  );
160	}
