3	const LOCALE = { INR: "en-IN", USD: "en-US" };
4	
5	export function money(value, currency) {
6	  if (value === null || value === undefined) return "–";
7	  return new Intl.NumberFormat(LOCALE[currency] || "en-US", {
8	    style: "currency",
9	    currency: currency || "USD",
10	    minimumFractionDigits: 2,
11	    maximumFractionDigits: 2,
12	  }).format(value);
13	}
14	
15	export function compactMoney(value, currency) {
16	  return new Intl.NumberFormat(LOCALE[currency] || "en-US", {
17	    style: "currency",
18	    currency: currency || "USD",
19	    notation: "compact",
20	    maximumFractionDigits: 1,
21	  }).format(value);
22	}
23	
24	export function number(value) {
25	  if (value === null || value === undefined) return "–";
26	  return new Intl.NumberFormat("en-US").format(value);
27	}
28	
29	export function signedMoney(value, currency) {
30	  const text = money(Math.abs(value), currency);
31	  if (value > 0) return `+${text}`;
32	  if (value < 0) return `−${text}`;
33	  return text;
34	}
35	
36	export function clock(iso) {
37	  if (!iso) return "–";
38	  return new Date(iso).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
39	}
40	
41	export function dateTime(iso) {
42	  if (!iso) return "–";
43	  return new Date(iso).toLocaleString([], {
44	    month: "short",
45	    day: "numeric",
46	    hour: "2-digit",
47	    minute: "2-digit",
48	    second: "2-digit",
49	  });
50	}
51	
52	export function shortDate(isoDate) {
53	  const [year, month, day] = isoDate.split("-").map(Number);
54	  return new Date(year, month - 1, day).toLocaleDateString([], { month: "short", day: "numeric" });
55	}
56	
57	export function ago(seconds) {
58	  if (seconds === null || seconds === undefined) return "never";
59	  if (seconds < 90) return `${Math.round(seconds)}s ago`;
60	  if (seconds < 5400) return `${Math.round(seconds / 60)} min ago`;
61	  return `${Math.round(seconds / 3600)} h ago`;
62	}
63	
64	export function titleCase(text) {
65	  return (text || "").replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());
66	}
67	
68	export function pretty(value) {
69	  return typeof value === "string" ? value : JSON.stringify(value, null, 2);
70	}
