// The incident console: is the data trustworthy, and if not, what is being done about it.
// Injecting faults and driving the demo environment live in a separate page, the Scenario Lab.
import { useEffect, useState } from "react";
import { getAccessCode, setAccessCode, usePoll } from "./api.js";
import { ago } from "./format.js";
import Audit from "./components/Audit.jsx";
import { AccessCode, Badge, ErrorNote, TRUST_TEXT } from "./components/common.jsx";
import { BrandMark, Icon } from "./components/icons.jsx";
import Incidents from "./components/Incident.jsx";
import Overview from "./components/Overview.jsx";

const LAB_URL = "/lab/";
const PAGES = [
  { key: "overview", label: "Overview", icon: "activity" },
  { key: "incidents", label: "Incidents", icon: "alert" },
  { key: "audit", label: "Audit log", icon: "list" },
];

// The view lives in the URL hash (#/incidents/INC-0001) so a reload or a
// shared link lands on the same page.
function readRoute() {
  const [page, id] = window.location.hash.replace(/^#\/?/, "").split("/");
  return { page: PAGES.some((p) => p.key === page) ? page : "overview", id: id || null };
}

function AgentCard({ agent }) {
  if (!agent) return null;
  const state = !agent.available ? "warning" : "good";
  return (
    <div className="agent-card">
      <div className="agent-card-title">
        <span className={`dot ${agent.investigation_running ? "dot-live" : `dot-${state}`}`} aria-hidden="true" />
        {agent.available ? (agent.investigation_running ? "Agent investigating" : "Agent available") : "Agent unavailable"}
      </div>
      {agent.available ? (
        <dl>
          <dt>Model</dt>
          <dd>{agent.model}</dd>
          <dt>Workflow</dt>
          <dd>{agent.workflow_version}</dd>
          <dt>Limit</dt>
          <dd>{agent.limits.per_hour} runs / hour</dd>
        </dl>
      ) : (
        <p>{agent.detail}</p>
      )}
    </div>
  );
}

export default function App() {
  const [route, setRoute] = useState(readRoute);
  const [code, setCode] = useState(getAccessCode);
  const metrics = usePoll("/metrics/summary", 2500);
  const agent = usePoll("/agent/status", 5000);

  useEffect(() => {
    // The lab used to be a tab of this page; old links to it still work.
    if (/^#\/?lab\b/.test(window.location.hash)) window.location.replace(LAB_URL);
    const onHash = () => setRoute(readRoute());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);

  const go = (page, id) => {
    window.location.hash = id ? `/${page}/${id}` : `/${page}`;
    window.scrollTo(0, 0);
  };
  const refreshAll = () => {
    metrics.refresh();
    agent.refresh();
  };

  const activeIncident = metrics.data?.active_incident;
  const trust = metrics.data?.trust;
  const pipeline = metrics.data?.pipeline;
  const current = PAGES.find((p) => p.key === route.page);

  return (
    <div className="shell">
      <aside className="sidebar">
        <a className="brand" href="#/overview">
          <BrandMark />
          <div>
            <div className="brand-name">DataTraceMind</div>
            <div className="brand-tag">Data reliability console</div>
          </div>
        </a>

        <div className="nav-label">Monitor</div>
        <nav aria-label="Sections">
          {PAGES.map((page) => (
            <button
              key={page.key}
              type="button"
              className={`nav-item ${route.page === page.key ? "active" : ""}`}
              aria-current={route.page === page.key ? "page" : undefined}
              onClick={() => go(page.key)}
            >
              <Icon name={page.icon} />
              {page.label}
              {page.key === "incidents" && activeIncident && (
                <span className="nav-count" title={`${activeIncident.incident_id} is open`}>
                  1
                </span>
              )}
            </button>
          ))}
        </nav>

        <div className="nav-label">Demo environment</div>
        <a className="nav-item" href={LAB_URL} target="_blank" rel="noreferrer">
          <Icon name="flask" />
          Scenario Lab
          <span className="nav-trailing">
            <Icon name="external" size={13} />
          </span>
        </a>
        <p className="nav-hint">Inject faults, run live traffic, and reset the environment. Opens in its own tab.</p>

        <div className="sidebar-foot">
          <AgentCard agent={agent.data} />
        </div>
      </aside>

      <div className="main">
        <header className="topbar">
          <nav className="crumbs" aria-label="Breadcrumb">
            <span>order_revenue</span>
            <Icon name="chevronRight" size={13} />
            {route.id ? (
              <>
                <button type="button" onClick={() => go(route.page)}>
                  {current.label}
                </button>
                <Icon name="chevronRight" size={13} />
                <span className="crumb-current">{route.id}</span>
              </>
            ) : (
              <span className="crumb-current">{current.label}</span>
            )}
          </nav>
          <div className="topbar-right">
            {pipeline && (
              <span className="topbar-meta" title="Time since the analytics target was last rebuilt">
                Refreshed {ago(pipeline.freshness_seconds)}
              </span>
            )}
            {trust && <Badge value={trust}>{TRUST_TEXT[trust]}</Badge>}
            {agent.data?.access_code_required && (
              <AccessCode
                value={code}
                onChange={(value) => {
                  setCode(value);
                  setAccessCode(value);
                }}
              />
            )}
          </div>
        </header>

        <main className="content">
          {metrics.error && !metrics.data && (
            <ErrorNote message={`Cannot reach the DataTraceMind API: ${metrics.error.message}`} />
          )}
          {route.page === "overview" && <Overview metrics={metrics.data} onOpenIncident={(id) => go("incidents", id)} />}
          {route.page === "incidents" && (
            <Incidents selectedId={route.id} onSelect={(id) => go("incidents", id)} agent={agent.data} onChanged={refreshAll} />
          )}
          {route.page === "audit" && <Audit />}
        </main>
      </div>
    </div>
  );
}

// Overview: is the data trustworthy right now, and what is the pipeline doing?
import { useState } from "react";
import { usePoll } from "../api.js";
import { ago, clock, money, number, signedMoney, titleCase } from "../format.js";
import { Badge, Card, Empty, PageHead, TRUST_TEXT } from "./common.jsx";
import { Icon } from "./icons.jsx";
import RevenueChart from "./RevenueChart.jsx";

const TRUST_DOT = { trustworthy: "good", under_investigation: "critical", stale: "warning", untrusted: "critical" };
const TRUST_NOTE = {
  trustworthy: "Analytics agrees with the source and is fresh.",
  under_investigation: "An incident is open. Treat the numbers below as suspect until it is resolved.",
  stale: "The analytics target has not refreshed within its objective.",
  untrusted: "Analytics disagrees with the source and no incident covers it yet.",
};

function TrustTile({ metrics, lastRun }) {
  const passed = lastRun ? lastRun.checks.filter((c) => c.passed).length : null;
  return (
    <div className="kpi">
      <div className="kpi-label">
        <Icon name="shield" size={14} /> Data trust
      </div>
      <div className="kpi-value kpi-value-text">
        <span className={`dot dot-${TRUST_DOT[metrics.trust]}`} aria-hidden="true" />
        {TRUST_TEXT[metrics.trust]}
      </div>
      <div className="kpi-foot muted">{TRUST_NOTE[metrics.trust]}</div>
      <dl className="kpi-breakdown">
        <div>
          <dt>Quality checks</dt>
          <dd>{lastRun ? `${passed} of ${lastRun.checks.length} passed` : "–"}</dd>
          <dd className="muted">{lastRun ? `on run #${lastRun.run_id}` : ""}</dd>
        </div>
        <div>
          <dt>Compared as of</dt>
          <dd>{clock(metrics.as_of)}</dd>
          <dd className="muted">last successful load</dd>
        </div>
      </dl>
    </div>
  );
}

function RevenueTile({ currency, sides }) {
  const matches = sides.within_tolerance;
  return (
    <div className="kpi">
      <div className="kpi-label">
        <Icon name="coins" size={14} /> Net revenue · {currency}
      </div>
      <div className="kpi-value">{money(sides.analytics.net, currency)}</div>
      <div className="kpi-foot">
        <Badge tone={matches ? "good" : "critical"}>
          {matches ? "Matches source" : `${signedMoney(sides.net_difference, currency)} vs source`}
        </Badge>
        <span className="muted">Source-derived {money(sides.source.net, currency)}</span>
      </div>
      <dl className="kpi-breakdown">
        <div>
          <dt>Gross paid</dt>
          <dd>{money(sides.analytics.gross, currency)}</dd>
          <dd className="muted">source {money(sides.source.gross, currency)}</dd>
        </div>
        <div>
          <dt>Refunds subtracted</dt>
          <dd>{money(sides.analytics.refunds, currency)}</dd>
          <dd className="muted">source {money(sides.source.refunds, currency)}</dd>
        </div>
      </dl>
    </div>
  );
}

function PipelineTile({ pipeline, orderCounts }) {
  const run = pipeline.last_run;
  const orders = Object.values(orderCounts).reduce(
    (sum, c) => ({ source: sum.source + c.source, analytics: sum.analytics + c.analytics }),
    { source: 0, analytics: 0 },
  );
  return (
    <div className="kpi">
      <div className="kpi-label">
        <Icon name="layers" size={14} /> Pipeline · order_revenue
      </div>
      <div className="kpi-value kpi-value-text">
        {run ? (
          <>
            <span className={`dot dot-${run.status === "SUCCESS" ? "good" : "critical"}`} aria-hidden="true" />
            Run #{run.run_id} {run.status === "SUCCESS" ? "succeeded" : run.status === "FAILED" ? "failed" : "running"}
          </>
        ) : (
          "No runs yet"
        )}
      </div>
      <div className="kpi-foot">
        <Badge tone={pipeline.fresh ? "good" : "warning"}>
          {pipeline.fresh ? "Fresh" : "Stale"} · refreshed {ago(pipeline.freshness_seconds)}
        </Badge>
      </div>
      {run?.error_summary && <p className="kpi-error">{run.error_summary}</p>}
      <dl className="kpi-breakdown">
        <div>
          <dt>Orders</dt>
          <dd>{number(orders.analytics)} in analytics</dd>
          <dd className="muted">{number(orders.source)} in source</dd>
        </div>
        <div>
          <dt>Transformation</dt>
          <dd>{pipeline.transform ? `Version ${pipeline.transform.version}` : "–"}</dd>
          <dd className="muted">{pipeline.transform?.author}</dd>
        </div>
      </dl>
    </div>
  );
}

function TrafficState({ traffic }) {
  if (!traffic) return null;
  return traffic.running ? (
    <span className="field-inline">
      <span className="dot dot-live" aria-hidden="true" /> Live · about {traffic.per_minute} per minute
    </span>
  ) : (
    <span className="field-inline muted" title="Live traffic is started from the Scenario Lab">
      <span className="dot" aria-hidden="true" /> No live traffic
    </span>
  );
}

function LiveFeed() {
  const { data } = usePoll("/transactions/live?limit=12", 2000);
  if (!data) return <Empty>Loading…</Empty>;
  return (
    <>
      <p className="muted feed-totals">
        {number(data.totals.orders)} orders · {number(data.totals.payments)} payments · {number(data.totals.refunds)} refunds in the source
      </p>
      <div className="table-scroll">
        <table className="table numeric">
          <thead>
            <tr>
              <th>Time</th>
              <th>Event</th>
              <th>Status</th>
              <th className="right">Amount</th>
            </tr>
          </thead>
          <tbody>
            {data.events.map((event) => (
              <tr key={`${event.kind}-${event.id}`}>
                <td className="muted nowrap">{clock(event.at)}</td>
                <td>
                  {titleCase(event.kind)} #{event.id}
                  {event.kind !== "order" && <span className="muted"> · order #{event.order_id}</span>}
                </td>
                <td>
                  <span className="status-text">{event.status}</span>
                </td>
                <td className="right nowrap">{money(event.amount, event.currency)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}

function RunHistory({ runs }) {
  if (!runs) return <Empty>Loading…</Empty>;
  if (runs.length === 0) return <Empty>No pipeline runs yet.</Empty>;
  return (
    <div className="table-scroll">
      <table className="table numeric">
        <thead>
          <tr>
            <th>Run</th>
            <th>Status</th>
            <th>Trigger</th>
            <th className="right">Loaded</th>
            <th>Quality checks</th>
          </tr>
        </thead>
        <tbody>
          {runs.map((run) => {
            const failed = run.checks.filter((c) => !c.passed);
            return (
              <tr key={run.run_id}>
                <td className="nowrap">
                  <span className="id">#{run.run_id}</span> <span className="muted">{clock(run.started_at)}</span>
                </td>
                <td>
                  <Badge value={run.status} />
                </td>
                <td className="muted">{titleCase(run.trigger)}</td>
                <td className="right">{number(run.loaded_count)}</td>
                <td>
                  {failed.length === 0 ? (
                    <span className="muted">{run.checks.length} passed</span>
                  ) : (
                    <span title={failed.map((c) => c.check_name).join("\n")}>
                      <Badge tone="critical">{failed.length} failed</Badge>{" "}
                      <span className="muted">
                        {failed[0].check_name}
                        {failed.length > 1 ? ` +${failed.length - 1}` : ""}
                      </span>
                    </span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export default function Overview({ metrics, onOpenIncident }) {
  const currencies = metrics ? Object.keys(metrics.reconciliation.by_currency) : [];
  const [currency, setCurrency] = useState("INR");
  const runs = usePoll("/pipeline/runs?limit=8", 3000);
  const traffic = usePoll("/demo/traffic", 4000);
  if (!metrics) return <Empty>Loading the dashboard…</Empty>;
  const selected = currencies.includes(currency) ? currency : currencies[0];
  const incident = metrics.active_incident;
  const lastRun = runs.data?.find((run) => run.status !== "RUNNING");

  return (
    <div className="stack">
      <PageHead
        title="Overview"
        subtitle="Whether the analytics target agrees with the source of truth, checked after every pipeline run."
      />

      {incident && (
        <div className={`banner ${incident.severity === "critical" ? "banner-critical" : ""}`} role="status">
          <div>
            <div className="banner-title">
              <span className="id">{incident.incident_id}</span>
              <Badge value={incident.severity} />
              <Badge value={incident.status} />
            </div>
            <p>{incident.summary}</p>
          </div>
          <button type="button" className="button button-primary" onClick={() => onOpenIncident(incident.incident_id)}>
            Open incident <Icon name="arrowRight" size={14} />
          </button>
        </div>
      )}

      <div className="kpis">
        <TrustTile metrics={metrics} lastRun={lastRun} />
        {currencies.map((code) => (
          <RevenueTile key={code} currency={code} sides={metrics.reconciliation.by_currency[code]} />
        ))}
        <PipelineTile pipeline={metrics.pipeline} orderCounts={metrics.order_counts} />
      </div>

      <Card
        title="Daily net revenue: source versus analytics"
        subtitle="Source-derived revenue is computed from the operational tables by the approved net_revenue contract."
        actions={
          currencies.length > 1 && (
            <label className="field-inline">
              Currency
              <select value={selected} onChange={(event) => setCurrency(event.target.value)}>
                {currencies.map((code) => (
                  <option key={code}>{code}</option>
                ))}
              </select>
            </label>
          )
        }
      >
        <RevenueChart daily={metrics.daily} currency={selected} tolerance={metrics.reconciliation.tolerance} />
      </Card>

      <div className="columns">
        <Card title="Source transactions" actions={<TrafficState traffic={traffic.data} />} flush>
          <LiveFeed />
        </Card>
        <Card title="Recent pipeline runs" flush>
          <RunHistory runs={runs.data} />
        </Card>
      </div>
    </div>
  );
}

// Incidents: the list, and one incident's page. The page reads top to bottom:
// anomaly -> evidence -> root cause -> patch -> staging proof -> human approval
// -> verified recovery.
import { useState } from "react";
import { api, useAction, usePoll } from "../api.js";
import { between, clock, dateTime, money, number, since, titleCase } from "../format.js";
import { Badge, Button, Card, Empty, ErrorNote, Facts, Json, PageHead, Segmented } from "./common.jsx";
import { Icon } from "./icons.jsx";
import RepairReview from "./RepairReview.jsx";

const LIFECYCLE = [
  ["detected", "Detected"],
  ["investigating", "Investigating"],
  ["diagnosed", "Diagnosed"],
  ["repair_proposed", "Repair proposed"],
  ["validating", "Validating"],
  ["awaiting_approval", "Awaiting approval"],
  ["applying", "Applying"],
  ["verifying", "Verifying"],
  ["resolved", "Resolved"],
];
const RESTARTABLE = new Set([
  "detected", "diagnosed", "repair_proposed", "validation_failed", "awaiting_approval", "application_failed",
  "rejected", "escalated",
]);
const OFF_PATH = new Set(["validation_failed", "application_failed", "rejected", "escalated"]);

function Lifecycle({ incident }) {
  const visited = new Set(incident.events.filter((e) => e.event_type === "lifecycle").map((e) => e.status));
  return (
    <ol className="lifecycle" aria-label="Incident lifecycle">
      {LIFECYCLE.map(([status, label]) => {
        const state = incident.status === status ? "current" : visited.has(status) ? "done" : "todo";
        return (
          <li key={status} className={`step step-${state}`} aria-current={state === "current" ? "step" : undefined}>
            <span className="step-dot" aria-hidden="true">
              {state === "done" ? "✓" : ""}
            </span>
            {label}
          </li>
        );
      })}
    </ol>
  );
}

function Trigger({ incident }) {
  const currencies = Object.keys(incident.source_metrics || {});
  return (
    <Card
      id="detection"
      title="What the monitor found"
      subtitle={`Deterministic checks after ETL run ${incident.trigger.etl_run_id ?? "–"} (${incident.trigger.etl_status ?? "freshness monitor"}). No model decides that something is wrong.`}
    >
      {currencies.length > 0 && (
        <div className="table-scroll">
          <table className="table table-inset numeric">
            <thead>
              <tr>
                <th>Currency</th>
                <th className="right">Source gross</th>
                <th className="right">Source refunds</th>
                <th className="right">Source net</th>
                <th className="right">Analytics gross</th>
                <th className="right">Analytics refunds</th>
                <th className="right">Analytics net</th>
              </tr>
            </thead>
            <tbody>
              {currencies.map((currency) => {
                const source = incident.source_metrics[currency];
                const target = incident.target_metrics[currency];
                return (
                  <tr key={currency}>
                    <td>{currency}</td>
                    <td className="right">{money(source.gross, currency)}</td>
                    <td className="right">{money(source.refunds, currency)}</td>
                    <td className="right">{money(source.net, currency)}</td>
                    <td className="right">{money(target.gross, currency)}</td>
                    <td className="right">{money(target.refunds, currency)}</td>
                    <td className="right">{money(target.net, currency)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
      <ul className="checks">
        {incident.trigger.failed_checks.map((check) => (
          <li key={check.check_name}>
            <details>
              <summary>
                <Badge value={check.severity}>{`Failed · ${check.severity}`}</Badge> <code>{check.check_name}</code>
                <span className="muted"> — expected: {check.expected_condition}</span>
              </summary>
              <Json value={check.observed_value} />
            </details>
          </li>
        ))}
      </ul>
    </Card>
  );
}

function Timeline({ events }) {
  return (
    <ol className="timeline">
      {events.map((event) => (
        <li key={event.event_id} className={`event event-${event.event_type}`}>
          <span className="event-time">{clock(event.created_at)}</span>
          <span className="event-agent">{titleCase(event.agent.replace(/^human:/, "human · "))}</span>
          <span className="event-body">
            <Badge value={event.status} />{" "}
            {event.event_type === "tool_call" && <span className="tag">tool</span>}
            {event.payload?.evidence_id && <span className="tag tag-strong">{event.payload.evidence_id}</span>} {event.summary}
            {event.payload?.input_tokens !== undefined && (
              <span className="muted">
                {" "}
                · {number(event.payload.input_tokens)} in / {number(event.payload.output_tokens)} out tokens · est. $
                {event.payload.est_cost_usd}
              </span>
            )}
          </span>
        </li>
      ))}
    </ol>
  );
}

function Evidence({ evidence, cited }) {
  if (evidence.length === 0) return <Empty>No evidence collected yet.</Empty>;
  return (
    <ul className="evidence">
      {evidence.map((item) => (
        <li key={item.evidence_id} id={item.evidence_id} className={cited.has(item.evidence_id) ? "evidence-cited" : ""}>
          <details>
            <summary>
              <span className="tag tag-strong">{item.evidence_id}</span> {item.description}
              <span className="muted">
                {" "}
                · {item.query_or_tool} · {item.source} · by {titleCase(item.collected_by)}
              </span>
              {cited.has(item.evidence_id) && <span className="tag">cited in root cause</span>}
            </summary>
            {Object.keys(item.arguments).length > 0 && (
              <p className="muted">
                Arguments: <code>{JSON.stringify(item.arguments)}</code>
              </p>
            )}
            <Json value={item.result_summary?.content ?? item.result_summary?.text ?? item.result_summary} />
          </details>
        </li>
      ))}
    </ul>
  );
}

function Hypotheses({ state }) {
  const hypotheses = state.hypotheses || [];
  if (hypotheses.length === 0) return null;
  const selected = state.selected_root_cause;
  return (
    <Card
      id="root-cause"
      title="Root cause"
      subtitle="Competing hypotheses ranked by the analyst. A cause counts as confirmed only when it cites evidence that exists and clears the confidence bar."
      actions={selected ? <Badge tone="good">Confirmed</Badge> : <Badge tone="warning">Not confirmed</Badge>}
    >
      {selected && (
        <div className="root-cause">
          <p>{selected.summary}</p>
          <p className="muted">
            Implicated: <code>{selected.implicated_component}</code>
          </p>
        </div>
      )}
      {state.analysis?.business_rule_ambiguity && (
        <p className="note note-error">Needs a human decision: {state.analysis.business_rule_ambiguity}</p>
      )}
      <ol className="hypotheses">
        {hypotheses.map((h) => (
          <li key={h.hypothesis_id} className={selected?.hypothesis_id === h.hypothesis_id ? "hypothesis-selected" : ""}>
            <div className="hypothesis-head">
              <span className="tag tag-strong">{h.hypothesis_id}</span>
              <span className="tag">{titleCase(h.category)}</span>
              <span className="meter" role="img" aria-label={`Confidence ${Math.round(h.confidence * 100)} percent`}>
                <span style={{ width: `${Math.round(h.confidence * 100)}%` }} />
              </span>
              <span className="muted">{Math.round(h.confidence * 100)}% confidence</span>
            </div>
            <p>{h.statement}</p>
            <p className="muted">{h.reasoning}</p>
            <p className="evidence-links">
              {h.supporting_evidence.length > 0 && <span className="muted">Supported by </span>}
              {h.supporting_evidence.map((id) => (
                <a
                  key={id}
                  className="tag tag-strong"
                  href={`#${id}`}
                  onClick={(e) => {
                    e.preventDefault();
                    document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "center" });
                  }}
                >
                  {id}
                </a>
              ))}
              {h.contradicting_evidence.length > 0 && <span className="muted"> Contradicted by </span>}
              {h.contradicting_evidence.map((id) => (
                <span key={id} className="tag tag-strong">
                  {id}
                </span>
              ))}
            </p>
          </li>
        ))}
      </ol>
    </Card>
  );
}

function Runs({ runs }) {
  if (runs.length === 0) return null;
  return (
    <Card
      id="runs"
      title="Investigation runs"
      subtitle="One row per run; each is one neatlogs trace. Cost is an estimate at API list prices (the model runs on a flat-rate plan)."
      flush
    >
      <div className="table-scroll">
        <table className="table numeric">
          <thead>
            <tr>
              <th>Run</th>
              <th>Outcome</th>
              <th>Workflow</th>
              <th>Model</th>
              <th className="right">Duration</th>
              <th className="right">Role turns</th>
              <th className="right">Tool calls</th>
              <th className="right">Failed / retries</th>
              <th className="right">Input tokens</th>
              <th className="right">Output tokens</th>
              <th className="right">Est. cost</th>
              <th>Trace ID</th>
            </tr>
          </thead>
          <tbody>
            {runs.map((run) => (
              <tr key={run.run_id}>
                <td>
                  <span className="id">#{run.run_id}</span>
                </td>
                <td>
                  <Badge value={run.status} />
                </td>
                <td>{run.workflow_version}</td>
                <td>{run.model}</td>
                <td className="right">{run.duration_s ? `${Number(run.duration_s).toFixed(0)}s` : "–"}</td>
                <td className="right">{run.role_turns}</td>
                <td className="right">{run.tool_calls}</td>
                <td className="right">
                  {run.failed_tool_calls} / {run.retries}
                </td>
                <td className="right" title={`${number(run.cached_input_tokens)} cached`}>
                  {number(run.input_tokens)}
                </td>
                <td className="right">{number(run.output_tokens)}</td>
                <td className="right">${Number(run.est_cost_usd).toFixed(3)}</td>
                <td>
                  <code>{run.trace_id ? `${run.trace_id.slice(0, 12)}…` : "not traced"}</code>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Card>
  );
}

// Facts about the incident and its latest investigation, beside the narrative.
function Aside({ incident }) {
  const trigger = incident.trigger;
  const run = incident.investigation_runs.at(-1);
  const sections = [
    ["detection", "Detection", `${trigger.failed_checks.length} failed checks`],
    (incident.state.hypotheses || []).length > 0 && ["root-cause", "Root cause", `${incident.state.hypotheses.length} hypotheses`],
    incident.proposal && ["repair", "Repair review", titleCase(incident.proposal.status)],
    ["workflow", "Agent workflow", `${incident.events.length} events`],
    ["evidence", "Evidence", `${incident.evidence.length} items`],
    incident.investigation_runs.length > 0 && ["runs", "Investigation runs", String(incident.investigation_runs.length)],
  ].filter(Boolean);
  return (
    <aside className="aside">
      <Card title="Incident details">
        <Facts
          rows={[
            ["Type", titleCase(incident.incident_type)],
            ["Severity", <Badge key="s" value={incident.severity} />],
            ["Detected", dateTime(incident.detected_at)],
            ["Detected by", titleCase(trigger.detected_by)],
            ["ETL run", trigger.etl_run_id ? `#${trigger.etl_run_id} · ${trigger.etl_status}` : null],
            ["Transformation", trigger.transform_version ? `Version ${trigger.transform_version}` : null],
            ["Resolved", incident.resolved_at ? dateTime(incident.resolved_at) : null],
            ["Time to resolve", incident.resolved_at ? between(incident.detected_at, incident.resolved_at) : null],
          ]}
        />
      </Card>
      {run && (
        <Card title="Latest investigation">
          <Facts
            rows={[
              ["Outcome", <Badge key="o" value={run.status} />],
              ["Model", run.model],
              ["Workflow", run.workflow_version],
              ["Duration", run.duration_s ? `${Number(run.duration_s).toFixed(0)}s` : null],
              ["Role turns", run.role_turns],
              ["Tool calls", run.tool_calls],
              ["Est. cost", `$${Number(run.est_cost_usd).toFixed(3)}`],
            ]}
          />
        </Card>
      )}
      <Card title="On this page">
        <ul className="section-nav">
          {sections.map(([id, label, detail]) => (
            <li key={id}>
              <a
                href={`#${id}`}
                onClick={(event) => {
                  // The hash holds the route, so scroll instead of navigating.
                  event.preventDefault();
                  document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
                }}
              >
                {label} <span className="muted">{detail}</span>
              </a>
            </li>
          ))}
        </ul>
      </Card>
    </aside>
  );
}

function IncidentDetail({ incidentId, agent, onChanged }) {
  const { data: incident, error, refresh } = usePoll(`/incidents/${incidentId}`, 2000);
  const action = useAction();
  const [showTools, setShowTools] = useState(true);
  if (error && !incident) return <ErrorNote message={error.message} />;
  if (!incident) return <Empty>Loading {incidentId}…</Empty>;

  const changed = async () => {
    await refresh();
    onChanged();
  };
  const investigate = () =>
    action.run(async () => {
      await api(`/incidents/${incidentId}/investigate`, { method: "POST" });
      await changed();
    });
  const cited = new Set(incident.state.selected_root_cause?.supporting_evidence || []);
  const events = showTools ? incident.events : incident.events.filter((e) => e.event_type !== "tool_call");
  const escalation = incident.state.errors?.at(-1);
  const canInvestigate = RESTARTABLE.has(incident.status);

  return (
    <div className="stack">
      <section className="card incident-hero">
        <div className="incident-head">
          <div>
            <h1>
              <span className="id">{incident.incident_id}</span> <Badge value={incident.severity} /> <Badge value={incident.status} />
            </h1>
            <p className="incident-summary">{incident.summary}</p>
            <p className="incident-meta">
              <span>{titleCase(incident.incident_type)}</span>
              <span>Detected {dateTime(incident.detected_at)}</span>
              <span>
                {incident.resolved_at
                  ? `Resolved in ${between(incident.detected_at, incident.resolved_at)}`
                  : `Open for ${since(incident.detected_at).replace(" ago", "")}`}
              </span>
            </p>
          </div>
          {canInvestigate && (
            <div className="incident-actions">
              <Button
                kind="primary"
                size="large"
                icon="zap"
                onClick={investigate}
                busy={action.busy}
                disabled={!agent?.available || agent?.investigation_running}
                title={agent?.available ? undefined : agent?.detail}
              >
                {incident.status === "detected" ? "Investigate" : "Investigate again"}
              </Button>
              {!agent?.available && <p className="muted">Agent unavailable. {agent?.detail}</p>}
            </div>
          )}
        </div>
        <ErrorNote message={action.error} onDismiss={action.clearError} />
        <Lifecycle incident={incident} />
        {OFF_PATH.has(incident.status) && (
          <p className="note note-error">
            <span>
              <strong>{titleCase(incident.status)}.</strong>{" "}
              {incident.status === "escalated" && escalation
                ? `A human needs to take this: ${escalation.reason}`
                : incident.events.at(-1)?.summary}
            </span>
          </p>
        )}
      </section>

      <div className="detail-grid">
        <div className="stack">
          <Trigger incident={incident} />
          <Hypotheses state={incident.state} />
          <RepairReview incident={incident} onChanged={changed} />

          <Card
            id="workflow"
            title="Agent workflow"
            subtitle="Every step the supervisor and the agent roles took, in order."
            actions={
              <label className="field-inline">
                <input type="checkbox" checked={showTools} onChange={(event) => setShowTools(event.target.checked)} /> Show tool calls
              </label>
            }
          >
            <Timeline events={events} />
          </Card>

          <Card
            id="evidence"
            title={`Evidence · ${incident.evidence.length} items`}
            subtitle="Each item is the recorded result of a tool call, a contract, or code as deployed. Open one to see exactly what was returned."
          >
            <Evidence evidence={incident.evidence} cited={cited} />
          </Card>

          <Runs runs={incident.investigation_runs} />
        </div>
        <Aside incident={incident} />
      </div>
    </div>
  );
}

const FILTERS = {
  all: () => true,
  open: (incident) => incident.status !== "resolved",
  resolved: (incident) => incident.status === "resolved",
};

function IncidentList({ incidents, onSelect }) {
  const [filter, setFilter] = useState("all");
  const shown = incidents.filter(FILTERS[filter]);
  const count = (name) => incidents.filter(FILTERS[name]).length;
  return (
    <div className="stack">
      <PageHead
        title="Incidents"
        subtitle="Opened by the monitor when a pipeline run fails a quality check. One incident stays open per unresolved problem."
        actions={
          <Segmented
            label="Filter incidents"
            value={filter}
            onChange={setFilter}
            options={[
              { value: "all", label: "All", count: count("all") },
              { value: "open", label: "Open", count: count("open") },
              { value: "resolved", label: "Resolved", count: count("resolved") },
            ]}
          />
        }
      />
      <Card flush>
        {shown.length === 0 ? (
          <div className="blank">
            <div className="blank-icon">
              <Icon name="check" size={20} />
            </div>
            <h2>{incidents.length === 0 ? "No incidents" : `No ${filter} incidents`}</h2>
            <p>
              {incidents.length === 0
                ? "Every quality check on the latest pipeline run passed. To see the workflow, inject a fault from the Scenario Lab."
                : "Nothing matches this filter."}
            </p>
            {incidents.length === 0 && (
              <a className="button" href="/lab/" target="_blank" rel="noreferrer">
                <Icon name="flask" size={14} /> Open the Scenario Lab
              </a>
            )}
          </div>
        ) : (
          <div className="table-scroll">
            <table className="table clickable">
              <thead>
                <tr>
                  <th>Incident</th>
                  <th>Severity</th>
                  <th>Status</th>
                  <th>Type</th>
                  <th>Summary</th>
                  <th>Detected</th>
                  <th className="right">Duration</th>
                </tr>
              </thead>
              <tbody>
                {shown.map((incident) => (
                  <tr key={incident.incident_id} onClick={() => onSelect(incident.incident_id)}>
                    <td className="nowrap">
                      <button type="button" className="link id" onClick={() => onSelect(incident.incident_id)}>
                        {incident.incident_id}
                      </button>
                    </td>
                    <td>
                      <Badge value={incident.severity} />
                    </td>
                    <td>
                      <Badge value={incident.status} />
                    </td>
                    <td className="nowrap">{titleCase(incident.incident_type)}</td>
                    <td>
                      <span className="cell-clip">{incident.summary}</span>
                    </td>
                    <td className="nowrap muted">{dateTime(incident.detected_at)}</td>
                    <td className="right nowrap muted">
                      {incident.resolved_at
                        ? between(incident.detected_at, incident.resolved_at)
                        : `${since(incident.detected_at).replace(" ago", "")} open`}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );
}

export default function Incidents({ selectedId, onSelect, agent, onChanged }) {
  const { data: incidents } = usePoll("/incidents", 3000);
  if (selectedId) return <IncidentDetail key={selectedId} incidentId={selectedId} agent={agent} onChanged={onChanged} />;
  if (!incidents) return <Empty>Loading incidents…</Empty>;
  return <IncidentList incidents={incidents} onSelect={onSelect} />;
}

