input.content:
// The Scenario Lab: break the demo pipeline on purpose, then watch DataTraceMind
// deal with it in the incident console. This page operates the demo
// environment (traffic, fault injection, reset); the console never does.
import { useState } from "react";
import { api, getAccessCode, setAccessCode, useAction, usePoll } from "../api.js";
import { ago, number, since, titleCase } from "../format.js";
import { AccessCode, Badge, Button, Card, ErrorNote, Facts, PageHead, TRUST_TEXT } from "../components/common.jsx";
import { BrandMark, Icon } from "../components/icons.jsx";
import InjectionResult from "./InjectionResult.jsx";
import ScenarioCatalog from "./ScenarioCatalog.jsx";
import TrafficPanel from "./TrafficPanel.jsx";

const CONSOLE_URL = "/";
const incidentUrl = (id) => `${CONSOLE_URL}#/incidents/${id}`;
// One named tab, so every link from the lab lands in the same console window.
const CONSOLE_TAB = "dtm-console";

const STEPS = [
  ["baseline", "Start from the baseline", "Seeded data, the repository's transformation, no incidents."],
  ["traffic", "Run live traffic", "Optional. Keeps new orders, payments, and refunds arriving."],
  ["inject", "Inject one fault", "Pick a scenario. The lab breaks the pipeline in that one way."],
  ["resolve", "Resolve it in the console", "Investigate, review the repair, approve. Then reset."],
];

// Where the run stands, derived from what is injected and what became of its incident.
function phaseOf(active, incident) {
  if (!active?.scenario_id) return "baseline";
  if (!incident) return "injected";
  return incident.status === "resolved" ? "resolved" : "incident";
}

function Flow({ phase, trafficRunning }) {
  const current = { baseline: "inject", injected: "resolve", incident: "resolve", resolved: "resolve" }[phase];
  const done = {
    baseline: true,
    traffic: trafficRunning,
    inject: phase !== "baseline",
    resolve: phase === "resolved",
  };
  return (
    <ol className="flow" aria-label="How a lab run works">
      {STEPS.map(([key, title, caption], index) => {
        const state = done[key] ? "done" : key === current ? "current" : "todo";
        return (
          <li key={key} className={`flow-step flow-${state}`} aria-current={state === "current" ? "step" : undefined}>
            <span className="flow-number" aria-hidden="true">
              {state === "done" ? <Icon name="check" size={13} /> : index + 1}
            </span>
            <div>
              <div className="flow-title">{title}</div>
              <div className="flow-caption">{caption}</div>
            </div>
          </li>
        );
      })}
    </ol>
  );
}

function Headline({ phase, active, incident, onReset, resetting }) {
  if (phase === "baseline")
    return (
      <div className="headline">
        <span className="dot dot-good" aria-hidden="true" />
        <div>
          <strong>The environment is at the clean baseline.</strong> Choose a scenario below, read what it does, and
          inject it. Only one fault can be active at a time.
        </div>
      </div>
    );
  const scenario = active.scenario_id;
  if (phase === "injected")
    return (
      <div className="headline headline-warning">
        <span className="dot dot-warning" aria-hidden="true" />
        <div>
          <strong>{scenario} is injected</strong> and the monitor has not opened an incident for it. Check the
          injection report below.
        </div>
      </div>
    );
  if (phase === "resolved")
    return (
      <div className="headline">
        <span className="dot dot-good" aria-hidden="true" />
        <div>
          <strong>{incident.incident_id} is resolved.</strong> The repair for {scenario} was approved, applied, and
          verified. Reset to the baseline to run another scenario.
        </div>
        <Button icon="reset" onClick={onReset} busy={resetting}>
          Reset to baseline
        </Button>
      </div>
    );
  return (
    <div className="headline headline-critical">
      <span className="dot dot-critical" aria-hidden="true" />
      <div>
        <strong>{scenario} is injected.</strong> The monitor opened {incident.incident_id}, now{" "}
        <Badge value={incident.status} />. Continue in the incident console: investigate, review the proposed repair,
        and decide.
      </div>
      <a className="button button-primary" href={incidentUrl(incident.incident_id)} target={CONSOLE_TAB}>
        Open {incident.incident_id} <Icon name="arrowRight" size={14} />
      </a>
    </div>
  );
}

function Environment({ lab, metrics, live, phase, incident, onReset, confirming, resetting }) {
  const pipeline = metrics?.pipeline;
  const run = pipeline?.last_run;
  const env = lab.environment;
  return (
    <Card
      title="Environment"
      subtitle="The demo stack this lab operates: a source database, the order_revenue pipeline, and its analytics target."
      actions={
        <Button
          kind="danger"
          icon="reset"
          onClick={onReset}
          busy={resetting}
          title="Restores the seeded data and the baseline transformation, clears every incident, and stops traffic"
        >
          {confirming ? "Click again to reset" : "Reset to baseline"}
        </Button>
      }
    >
      <Facts
        rows={[
          [
            "State",
            phase === "baseline" ? (
              <Badge key="b" tone="good">
                Clean baseline
              </Badge>
            ) : (
              <span key="f">
                <Badge tone="serious">{lab.active.scenario_id} injected</Badge>{" "}
                <span className="muted">{since(lab.active.injected_at)}</span>
              </span>
            ),
          ],
          ["Data trust", metrics ? <Badge key="t" value={metrics.trust}>{TRUST_TEXT[metrics.trust]}</Badge> : null],
          [
            "Open incident",
            incident && incident.status !== "resolved" ? (
              <a key="i" href={incidentUrl(incident.incident_id)} target={CONSOLE_TAB}>
                {incident.incident_id} · {titleCase(incident.status)}
              </a>
            ) : (
              "None"
            ),
          ],
          [
            "Last pipeline run",
            run ? `#${run.run_id} ${run.status} · refreshed ${ago(pipeline.freshness_seconds)}` : null,
          ],
          ["Pipeline schedule", `Every ${number(env.etl_interval_seconds)} seconds`],
          [
            "Transformation",
            pipeline?.transform ? `Version ${pipeline.transform.version} · ${pipeline.transform.author}` : null,
          ],
          [
            "Source rows",
            live
              ? `${number(live.totals.orders)} orders · ${number(live.totals.payments)} payments · ${number(live.totals.refunds)} refunds`
              : null,
          ],
          ["Baseline seed", `${env.seed} · ${number(env.seed_orders)} orders over ${env.seed_days} days`],
        ]}
      />
    </Card>
  );
}

export default function LabApp() {
  const [code, setCode] = useState(getAccessCode);
  const [confirmingReset, setConfirmingReset] = useState(false);
  const lab = usePoll("/scenarios", 3000);
  const metrics = usePoll("/metrics/summary", 2500);
  const traffic = usePoll("/demo/traffic", 2000);
  const live = usePoll("/transactions/live?limit=6", 2000);
  const incidents = usePoll("/incidents", 3000);
  const agent = usePoll("/agent/status", 10000);
  const resetAction = useAction();
  const injectAction = useAction();

  const refreshAll = () => Promise.all([lab, metrics, traffic, live, incidents].map((poll) => poll.refresh()));

  // Reset wipes every incident, so it takes two clicks; the second must come
  // within a few seconds or the button returns to its first state.
  const reset = async () => {
    if (!confirmingReset && phase !== "resolved") {
      setConfirmingReset(true);
      window.setTimeout(() => setConfirmingReset(false), 4000);
      return;
    }
    setConfirmingReset(false);
    await resetAction.run(() => api("/demo/reset", { method: "POST" }));
    await refreshAll();
  };
  const inject = async (scenarioId) => {
    await injectAction.run(() => api(`/scenarios/${scenarioId}/inject`, { method: "POST" }));
    await refreshAll();
    document.getElementById("result")?.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  const active = lab.data?.active;
  const incidentId = active?.injection_report?.incident_id;
  const incident = incidentId ? incidents.data?.find((row) => row.incident_id === incidentId) : null;
  const phase = phaseOf(active, incident);
  const activeScenario = lab.data?.scenarios.find((s) => s.scenario_id === active?.scenario_id);

  return (
    <div className="lab">
      <header className="lab-bar">
        <a className="brand" href="/lab/">
          <BrandMark />
          <div>
            <div className="brand-name">Scenario Lab</div>
            <div className="brand-tag">DataTraceMind demo environment</div>
          </div>
        </a>
        <span className="lab-env" title="Everything on this page acts on the disposable demo environment">
          <Icon name="flask" size={13} /> Simulation
        </span>
        <span className="spacer" />
        {agent.data?.access_code_required && (
          <AccessCode
            value={code}
            onChange={(value) => {
              setCode(value);
              setAccessCode(value);
            }}
          />
        )}
        <a className="lab-link" href={CONSOLE_URL} target={CONSOLE_TAB}>
          Incident console <Icon name="external" size={13} />
        </a>
      </header>

      <main className="content">
        <PageHead
          title="Scenario Lab"
          subtitle="Break the demo pipeline in one known way, then resolve it in the incident console. DataTraceMind is never told which fault is active: it has to find the cause from the same evidence an engineer would have."
        />

        {lab.error && !lab.data && <ErrorNote message={`Cannot reach the DataTraceMind API: ${lab.error.message}`} />}
        <ErrorNote message={resetAction.error} onDismiss={resetAction.clearError} />

        {lab.data && (
          <div className="stack">
            <Flow phase={phase} trafficRunning={Boolean(traffic.data?.running)} />
            <Headline phase={phase} active={active} incident={incident} onReset={reset} resetting={resetAction.busy} />

            <div className="lab-row">
              <Environment
                lab={lab.data}
                metrics={metrics.data}
                live={live.data}
                phase={phase}
                incident={incident}
                onReset={reset}
                confirming={confirmingReset}
                resetting={resetAction.busy}
              />
              <TrafficPanel
                traffic={traffic.data}
                live={live.data}
                etlInterval={lab.data.environment.etl_interval_seconds}
                onChanged={refreshAll}
              />
            </div>

            {activeScenario && (
              <InjectionResult
                scenario={activeScenario}
                active={active}
                incident={incident}
                incidentUrl={incidentUrl}
                consoleTab={CONSOLE_TAB}
              />
            )}

            <ScenarioCatalog
              scenarios={lab.data.scenarios}
              active={active}
              incident={incident}
              incidentUrl={incidentUrl}
              consoleTab={CONSOLE_TAB}
              onInject={inject}
              injecting={injectAction.busy}
              error={injectAction.error}
              onDismissError={injectAction.clearError}
            />
          </div>
        )}
      </main>
    </div>
  );
}

// Source traffic: the simulated customers behind the source database.
// One switch, one rate, and a count of what the stream has written.
import { api, useAction } from "../api.js";
import { clock, money, number, since, titleCase } from "../format.js";
import { Badge, Button, Card, ErrorNote, Segmented } from "../components/common.jsx";

const BATCH_SIZE = 25;
const PROFILE_HINT = {
  light: "A quiet shop: easy to follow row by row",
  steady: "The default pace",
  busy: "A rush: differences grow visibly within seconds",
};

function Counter({ label, value }) {
  return (
    <div className="counter">
      <div className="counter-value">{number(value)}</div>
      <div className="counter-label">{label}</div>
    </div>
  );
}

export default function TrafficPanel({ traffic, live, etlInterval, onChanged }) {
  const action = useAction();
  if (!traffic) return <Card title="Source traffic">Loading…</Card>;

  const post = (path, body) =>
    action.run(async () => {
      await api(path, { method: "POST", body });
      await onChanged();
    });
  // Choosing a rate while the stream runs changes it in place; while paused it
  // only sets the rate the next start will use.
  const setProfile = (profile) => post("/demo/traffic/start", { profile }).then(() => !traffic.running && post("/demo/traffic/stop"));

  return (
    <Card
      title="Source traffic"
      subtitle="Simulated customers placing orders, paying, and asking for refunds in the source database."
      actions={
        traffic.running ? (
          <span className="field-inline">
            <span className="dot dot-live" aria-hidden="true" /> Running · about {traffic.per_minute} per minute
          </span>
        ) : (
          <Badge tone="neutral">Paused</Badge>
        )
      }
    >
      <ErrorNote message={action.error} onDismiss={action.clearError} />
      <div className="traffic-controls">
        <Button
          kind={traffic.running ? "default" : "primary"}
          icon={traffic.running ? "pause" : "play"}
          busy={action.busy}
          onClick={() => post(traffic.running ? "/demo/traffic/stop" : "/demo/traffic/start", traffic.running ? undefined : { profile: traffic.profile })}
        >
          {traffic.running ? "Pause traffic" : "Start traffic"}
        </Button>
        <Segmented
          label="Traffic rate"
          value={traffic.profile}
          disabled={action.busy}
          onChange={setProfile}
          options={traffic.profiles.map((profile) => ({
            value: profile.name,
            label: `${titleCase(profile.name)} · ${profile.per_minute}/min`,
            title: PROFILE_HINT[profile.name],
          }))}
        />
        <span className="spacer" />
        <Button
          kind="ghost"
          icon="send"
          busy={action.busy}
          onClick={() => post("/demo/traffic/batch", { size: BATCH_SIZE })}
          title={`Writes ${BATCH_SIZE} transactions at once, whether or not the stream is running`}
        >
          Send {BATCH_SIZE} now
        </Button>
      </div>

      <div className="counters">
        <Counter label="Orders placed" value={traffic.counts.orders_placed} />
        <Counter label="Refunds requested" value={traffic.counts.refunds_requested} />
        <Counter label="Refunds settled" value={traffic.counts.refunds_settled} />
      </div>
      <p className="muted traffic-caption">
        Written by this lab since the last reset.{" "}
        {traffic.last_action_at ? `Last transaction ${since(traffic.last_action_at)}.` : "Nothing sent yet."}
      </p>

      <ul className="explain">
        <li>
          <strong>Optional.</strong> Every scenario reproduces on the seeded baseline with traffic paused.
        </li>
        <li>
          New rows reach analytics on the next pipeline run, every {number(etlInterval)} seconds.
        </li>
        <li>
          With a fault injected, the error keeps growing while traffic runs, as it would in production.
        </li>
        <li>A reset pauses traffic, so every run starts from the same baseline.</li>
      </ul>

      {live && (
        <div className="table-scroll">
          <table className="table table-inset numeric">
            <thead>
              <tr>
                <th>Latest in the source</th>
                <th>Status</th>
                <th className="right">Amount</th>
                <th className="right">Time</th>
              </tr>
            </thead>
            <tbody>
              {live.events.slice(0, 4).map((event) => (
                <tr key={`${event.kind}-${event.id}`}>
                  <td>
                    {titleCase(event.kind)} #{event.id}
                  </td>
                  <td>
                    <span className="status-text">{event.status}</span>
                  </td>
                  <td className="right nowrap">{money(event.amount, event.currency)}</td>
                  <td className="right nowrap muted">{clock(event.at)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </Card>
  );
}

// The scenario catalogue: every fault the lab can inject, explained before you inject it.
import { useState } from "react";
import { dateTime } from "../format.js";
import { Badge, Button, Card, ErrorNote, Segmented } from "../components/common.jsx";
import { Icon } from "../components/icons.jsx";

const FILTERS = {
  all: { label: "All", test: () => true },
  silent: { label: "Job stays green", test: (s) => s.etl_reports === "SUCCESS" },
  failing: { label: "Job fails", test: (s) => s.etl_reports !== "SUCCESS" },
  repair: { label: "Ends in a repair", test: (s) => s.resolution === "repair" },
  escalation: { label: "Ends in an escalation", test: (s) => s.resolution === "escalation" },
};

function JobBadge({ scenario }) {
  return scenario.etl_reports === "SUCCESS" ? (
    <Badge tone="good" title="The ETL job keeps reporting SUCCESS, so nothing looks wrong from the outside">
      Job reports SUCCESS
    </Badge>
  ) : (
    <Badge tone="critical" title="The ETL job fails outright">
      Job reports FAILED
    </Badge>
  );
}

function OutcomeBadge({ scenario }) {
  return scenario.resolution === "repair" ? (
    <Badge tone="active" title="A repair is proposed, proven in staging, and applied once you approve it">
      Repair for approval
    </Badge>
  ) : (
    <Badge tone="warning" title="No automatic fix is right; the workflow hands the incident to a person">
      Escalates to a human
    </Badge>
  );
}

function ScenarioRow({ scenario, selected, injected, onSelect }) {
  return (
    <li>
      <button
        type="button"
        className={`scenario-row ${selected ? "selected" : ""}`}
        aria-pressed={selected}
        onClick={() => onSelect(scenario.scenario_id)}
      >
        <span className="scenario-row-id id">{scenario.scenario_id}</span>
        <span className="scenario-row-text">
          <span className="scenario-row-name">{scenario.name}</span>
          <span className="scenario-row-meta">
            {scenario.layer} · {scenario.failure_type}
          </span>
        </span>
        {injected ? <Badge tone="serious">Injected</Badge> : <Icon name="chevronRight" size={14} />}
      </button>
    </li>
  );
}

function Brief({ title, children }) {
  return (
    <div className="brief">
      <dt>{title}</dt>
      <dd>{children}</dd>
    </div>
  );
}

function ScenarioDetail({ scenario, active, incident, incidentUrl, consoleTab, onInject, injecting }) {
  const activeId = active?.scenario_id;
  const isActive = activeId === scenario.scenario_id;
  return (
    <article className="scenario-detail" aria-live="polite">
      <header className="scenario-detail-head">
        <div className="row">
          <span className="id">{scenario.scenario_id}</span>
          <span className="tag">{scenario.priority}</span>
          <span className="tag">{scenario.failure_type}</span>
        </div>
        <h2>{scenario.name}</h2>
        <p>{scenario.description}</p>
      </header>

      <div className="scenario-facts">
        <div>
          <div className="eyebrow">Where the fault lives</div>
          <div className="scenario-fact">{scenario.layer}</div>
        </div>
        <div>
          <div className="eyebrow">What the job says</div>
          <JobBadge scenario={scenario} />
        </div>
        <div>
          <div className="eyebrow">How it should end</div>
          <OutcomeBadge scenario={scenario} />
        </div>
      </div>

      <dl className="briefs">
        <Brief title="What the lab changes">{scenario.injection}</Brief>
        <Brief title="What you will see">
          <ul className="bullets">
            {scenario.symptoms.map((symptom) => (
              <li key={symptom}>{symptom}</li>
            ))}
          </ul>
        </Brief>
        <Brief title="Checks that should fail">
          <span className="chips">
            {scenario.expected_failed_checks.map((check) => (
              <code key={check}>{check}</code>
            ))}
          </span>
        </Brief>
        <Brief title="Why it matters">{scenario.impact}</Brief>
        <Brief title="Expected resolution">{scenario.resolution_note}</Brief>
      </dl>

      <footer className="scenario-action">
        {isActive ? (
          <>
            <Badge tone="serious">Injected {dateTime(active.injected_at)}</Badge>
            {incident && (
              <a className="button button-primary" href={incidentUrl(incident.incident_id)} target={consoleTab}>
                Open {incident.incident_id} in the console <Icon name="arrowRight" size={14} />
              </a>
            )}
          </>
        ) : (
          <>
            <Button
              kind="primary"
              size="large"
              icon="zap"
              onClick={() => onInject(scenario.scenario_id)}
              busy={injecting}
              disabled={Boolean(activeId)}
            >
              Inject fault
            </Button>
            <span className="muted">
              {activeId
                ? `${activeId} is injected. Reset to the baseline before injecting another scenario.`
                : "Applies the fault and runs the pipeline so the monitor can react. Takes a few seconds."}
            </span>
          </>
        )}
      </footer>
    </article>
  );
}

export default function ScenarioCatalog({
  scenarios, active, incident, incidentUrl, consoleTab, onInject, injecting, error, onDismissError,
}) {
  const [filter, setFilter] = useState("all");
  const [chosen, setChosen] = useState(null);
  const shown = scenarios.filter(FILTERS[filter].test);
  // Follow the injected scenario until the operator picks another one to read.
  const selectedId = chosen ?? active?.scenario_id ?? scenarios[0].scenario_id;
  const selected = shown.find((s) => s.scenario_id === selectedId) ?? shown[0];

  return (
    <Card
      id="scenarios"
      title={`Fault scenarios · ${scenarios.length}`}
      subtitle="Each one introduces a single deterministic fault. Select a scenario to read what it changes, what you should see, and how the incident is expected to end."
      actions={
        <Segmented
          label="Filter scenarios"
          value={filter}
          onChange={setFilter}
          options={Object.entries(FILTERS).map(([value, { label, test }]) => ({
            value,
            label,
            count: scenarios.filter(test).length,
          }))}
        />
      }
    >
      <ErrorNote message={error} onDismiss={onDismissError} />
      <div className="catalog">
        <ul className="scenario-list" aria-label="Scenarios">
          {shown.map((scenario) => (
            <ScenarioRow
              key={scenario.scenario_id}
              scenario={scenario}
              selected={scenario.scenario_id === selected?.scenario_id}
              injected={scenario.scenario_id === active?.scenario_id}
              onSelect={setChosen}
            />
          ))}
        </ul>
        {selected && (
          <ScenarioDetail
            scenario={selected}
            active={active}
            incident={incident}
            incidentUrl={incidentUrl}
            consoleTab={consoleTab}
            onInject={onInject}
            injecting={injecting}
          />
        )}
      </div>
    </Card>
  );
}

// What the injection did: the pipeline runs it caused, which checks failed
// against which were expected to, and the revenue figures before and after.
import { dateTime, money, number, signedMoney, titleCase } from "../format.js";
import { Badge, Card } from "../components/common.jsx";
import { Icon } from "../components/icons.jsx";

function MetricsTable({ baseline, after }) {
  const currencies = Object.keys(baseline.by_currency);
  return (
    <div className="table-scroll">
      <table className="table table-inset numeric">
        <thead>
          <tr>
            <th>Currency</th>
            <th className="right">Source-derived net</th>
            <th className="right">Analytics net before</th>
            <th className="right">Analytics net after</th>
            <th>Analytics vs source</th>
          </tr>
        </thead>
        <tbody>
          {currencies.map((currency) => {
            const before = baseline.by_currency[currency];
            const now = after?.by_currency[currency];
            return (
              <tr key={currency}>
                <td>{currency}</td>
                <td className="right">{money((now || before).source.net, currency)}</td>
                <td className="right">{money(before.analytics.net, currency)}</td>
                <td className="right">{now ? money(now.analytics.net, currency) : "–"}</td>
                <td>
                  {!now ? (
                    "–"
                  ) : now.within_tolerance ? (
                    <Badge tone="good">Matches</Badge>
                  ) : (
                    <Badge tone="critical">{signedMoney(now.net_difference, currency)}</Badge>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function describeRun(run) {
  const parts = [run.full_refresh ? "full rebuild" : "incremental"];
  parts.push(`${number(run.loaded)} rows loaded`);
  if (run.rejected) parts.push(`${number(run.rejected)} rejected`);
  parts.push(`transformation v${run.transform_version}`);
  return parts.join(" · ");
}

export default function InjectionResult({ scenario, active, incident, incidentUrl, consoleTab }) {
  const report = active.injection_report;
  const runs = report?.runs || [];
  const failed = new Set(runs.at(-1)?.failed_checks || []);
  const expected = scenario.expected_failed_checks;
  const unexpected = [...failed].filter((name) => !expected.includes(name));
  const after = active.post_injection_metrics;

  return (
    <Card
      id="result"
      title={`Injection report · ${scenario.scenario_id}`}
      subtitle={`${scenario.name}. Injected ${dateTime(active.injected_at)}.`}
      actions={
        incident && (
          <a className="button" href={incidentUrl(incident.incident_id)} target={consoleTab}>
            {incident.incident_id} · {titleCase(incident.status)} <Icon name="external" size={13} />
          </a>
        )
      }
    >
      <div className="result-grid">
        <div>
          <h4>Pipeline runs caused by the injection</h4>
          <ol className="run-list">
            {runs.map((run) => (
              <li key={run.run_id}>
                <span className="id">#{run.run_id}</span>
                <Badge value={run.status} />
                <span>
                  {describeRun(run)}
                  <span className="muted">
                    {" "}
                    ·{" "}
                    {run.failed_checks.length === 0
                      ? "every check passed"
                      : `${run.failed_checks.length} checks failed`}
                  </span>
                  {run.error_summary && <span className="run-error">{run.error_summary}</span>}
                </span>
              </li>
            ))}
          </ol>
          {runs.length > 1 && (
            <p className="muted">
              This fault needs two runs: the first looks healthy, the second is where it bites.
            </p>
          )}

          <h4>Quality checks: expected against observed</h4>
          <ul className="check-list">
            {expected.map((name) => (
              <li key={name}>
                {failed.has(name) ? <Badge tone="good">Failed as expected</Badge> : <Badge tone="warning">Did not fail</Badge>}
                <code>{name}</code>
              </li>
            ))}
            {unexpected.map((name) => (
              <li key={name}>
                <Badge tone="neutral">Also failed</Badge>
                <code>{name}</code>
              </li>
            ))}
          </ul>
        </div>

        <div>
          <h4>Net revenue before and after</h4>
          {active.baseline_metrics && <MetricsTable baseline={active.baseline_metrics} after={after} />}
          {after && (
            <p className="muted result-note">
              {after.reconciled
                ? "Revenue still reconciles for every currency and day. This fault shows in row counts, not in revenue."
                : after.mismatched_day_count > 0 && Object.values(after.by_currency).every((c) => c.within_tolerance)
                  ? `Currency totals reconcile, but ${after.mismatched_day_count} days do not.`
                  : `${after.mismatched_day_count} days do not reconcile with the source.`}
            </p>
          )}
          <p className="note note-info">
            <span>
              {incident ? (
                <>
                  The monitor opened <strong>{incident.incident_id}</strong>. It carries the failed checks and nothing about
                  this scenario.
                </>
              ) : (
                "The monitor opened no incident for this injection."
              )}
            </span>
          </p>
        </div>
      </div>
    </Card>
  );
}

/* Scenario Lab. Builds on the shared design system in ../styles.css; only what
   the lab alone needs is here. Its header bar marks it as a different tool
   from the incident console. */

.lab { min-height: 100vh; display: flex; flex-direction: column; }
.lab-bar {
  position: sticky; top: 0; z-index: 20; height: 56px;
  display: flex; align-items: center; gap: 14px; padding: 0 28px;
  background: var(--nav); color: var(--nav-text); border-bottom: 3px solid var(--warning);
}
.lab-bar .brand { padding: 0; }
.lab-env {
  display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 650; letter-spacing: 0.06em;
  text-transform: uppercase; color: #1c1300; background: var(--warning); padding: 3px 9px; border-radius: 999px;
}
.lab-link {
  display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: var(--radius-sm);
  border: 1px solid var(--nav-border); background: var(--nav-raised); color: var(--nav-text-strong); font-weight: 600;
}
.lab-link:hover { text-decoration: none; border-color: var(--nav-text-muted); }
.lab-bar .access-code { background: var(--nav-raised); border-color: var(--nav-border); color: var(--nav-text-strong); }

.lab-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(420px, 1fr)); gap: 16px; align-items: stretch; }
.lab-row > * { min-width: 0; }
@media (max-width: 520px) { .lab-row { grid-template-columns: minmax(0, 1fr); } .lab-bar { padding: 0 16px; } }

/* --- The four steps of a run ------------------------------------------------ */

.flow { list-style: none; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-sm); overflow: hidden; }
.flow-step { display: flex; gap: 12px; align-items: flex-start; padding: 13px 16px; border-left: 1px solid var(--border); position: relative; }
.flow-step:first-child { border-left: 0; }
.flow-number {
  flex: none; width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font-size: 12px; font-weight: 650;
  border: 1.5px solid var(--border-strong); color: var(--text-muted); background: var(--surface);
}
.flow-title { font-weight: 650; font-size: 13px; }
.flow-caption { font-size: 12px; color: var(--text-muted); line-height: 1.45; margin-top: 1px; }
.flow-todo .flow-title { color: var(--text-secondary); }
.flow-done .flow-number { background: var(--good-wash); border-color: var(--good); color: var(--good-ink); }
.flow-current { background: var(--accent-wash); box-shadow: inset 0 -2px 0 var(--accent); }
.flow-current .flow-number { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
@media (max-width: 900px) {
  .flow { grid-template-columns: minmax(0, 1fr); }
  .flow-step { border-left: 0; border-top: 1px solid var(--border); }
  .flow-step:first-child { border-top: 0; }
}

.headline {
  display: flex; flex-wrap: wrap; align-items: center; gap: 12px 16px; padding: 13px 18px;
  background: var(--surface); border: 1px solid var(--border); border-left: 4px solid var(--good);
  border-radius: var(--radius); box-shadow: var(--shadow-sm);
}
.headline > div { flex: 1 1 420px; min-width: 0; }
.headline-warning { border-left-color: var(--warning); }
.headline-critical { border-left-color: var(--critical); }

/* --- Source traffic --------------------------------------------------------- */

.traffic-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.counters { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; margin-top: 14px; border: 1px solid var(--border); border-radius: var(--radius-sm); }
.counter { padding: 10px 14px; border-left: 1px solid var(--border); }
.counter:first-child { border-left: 0; }
.counter-value { font-size: 20px; font-weight: 650; letter-spacing: -0.01em; line-height: 1.2; }
.counter-label { font-size: 11.5px; color: var(--text-muted); }
.traffic-caption { font-size: 12px; margin-top: 6px; }
.explain { list-style: none; margin: 12px 0 14px; display: grid; gap: 4px; font-size: 12.5px; color: var(--text-secondary); }
.explain li { padding-left: 14px; position: relative; }
.explain li::before { content: ""; position: absolute; left: 2px; top: 0.62em; width: 4px; height: 4px; border-radius: 50%; background: var(--text-muted); }
.explain strong { color: var(--text); }

/* --- Scenario catalogue ----------------------------------------------------- */

.catalog { display: grid; grid-template-columns: minmax(280px, 380px) minmax(0, 1fr); gap: 0; border: 1px solid var(--border); border-radius: var(--radius-sm); overflow: hidden; }
@media (max-width: 960px) { .catalog { grid-template-columns: minmax(0, 1fr); } }
.scenario-list { list-style: none; background: var(--surface-sunken); border-right: 1px solid var(--border); }
@media (max-width: 960px) { .scenario-list { border-right: 0; border-bottom: 1px solid var(--border); } }
.scenario-list li + li { border-top: 1px solid var(--border); }
.scenario-row {
  appearance: none; border: 0; background: none; width: 100%; text-align: left; cursor: pointer; font: inherit; color: inherit;
  display: flex; align-items: center; gap: 12px; padding: 11px 14px;
}
.scenario-row:hover { background: var(--surface-hover); }
.scenario-row.selected { background: var(--surface); box-shadow: inset 3px 0 0 var(--accent); }
.scenario-row > .icon { color: var(--text-muted); }
.scenario-row-id { flex: none; color: var(--text-secondary); }
.scenario-row.selected .scenario-row-id { color: var(--accent); }
.scenario-row-text { flex: 1; min-width: 0; display: grid; gap: 1px; }
.scenario-row-name { font-weight: 600; }
.scenario-row-meta { font-size: 11.5px; color: var(--text-muted); }

.scenario-detail { padding: 18px 22px 20px; min-width: 0; }
.scenario-detail-head h2 { font-size: 17px; letter-spacing: -0.01em; margin: 8px 0 6px; }
.scenario-detail-head p { color: var(--text-secondary); max-width: 80ch; }
.scenario-facts {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px 20px; margin: 16px 0 4px; padding: 12px 14px;
  background: var(--surface-sunken); border: 1px solid var(--border); border-radius: var(--radius-sm);
}
.scenario-facts .eyebrow { margin-bottom: 4px; }
.scenario-fact { font-weight: 600; }
.briefs { margin: 4px 0 0; }
.brief { display: grid; grid-template-columns: 180px minmax(0, 1fr); gap: 4px 20px; padding: 12px 0; border-top: 1px solid var(--border); }
.brief:first-child { border-top: 0; }
.brief dt { font-weight: 600; color: var(--text-secondary); font-size: 12.5px; }
.brief dd { margin: 0; max-width: 78ch; }
@media (max-width: 700px) { .brief { grid-template-columns: minmax(0, 1fr); } }
.bullets { list-style: none; display: grid; gap: 4px; }
.bullets li { padding-left: 14px; position: relative; }
.bullets li::before { content: ""; position: absolute; left: 2px; top: 0.62em; width: 4px; height: 4px; border-radius: 50%; background: var(--text-muted); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.scenario-action { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 14px; margin-top: 6px; padding-top: 16px; border-top: 1px solid var(--border); }
.scenario-action .muted { flex: 1 1 260px; font-size: 12.5px; }

/* --- Injection report ------------------------------------------------------- */

.result-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(380px, 1fr)); gap: 8px 32px; }
.result-grid > * { min-width: 0; }
.result-grid h4:first-child { margin-top: 0; }
.run-list, .check-list { list-style: none; display: grid; gap: 6px; }
.run-list li { display: grid; grid-template-columns: auto auto minmax(0, 1fr); gap: 10px; align-items: baseline; font-size: 12.5px; }
.run-error { display: block; color: var(--critical-ink); overflow-wrap: anywhere; }
.check-list li { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.result-note { margin-top: 8px; font-size: 12.5px; }

